<template>
  <view class="search-page">
    <input 
      v-model="keyword" 
      placeholder="请输入企业名称" 
      confirm-type="search"
      @confirm="doSearch"
    />
    <button @click="doSearch">搜索</button>

    <view v-if="loading">加载中...</view>
    <view v-else-if="list.length === 0 && keyword">暂无数据</view>
    <view v-else>
      <view 
        v-for="item in list" 
        :key="item._id" 
        class="list-item"
        @click="goDetail(item._id)"
      >
        <text class="name">{{ item.company_name }}</text>
        <text class="info">{{ item.legal_person }} | {{ item.industry }}</text>
        <text class="address">{{ item.address }}</text>
      </view>
    </view>
  </view>
</template>

<script>
export default {
  data() {
    return {
      keyword: '',
      list: [],
      loading: false,
      pageIndex: 1,
      pageSize: 20,
      hasMore: true
    };
  },
  methods: {
    async doSearch(refresh = true) {
      if (!this.keyword.trim()) {
        uni.showToast({ title: '请输入企业名称', icon: 'none' });
        return;
      }
      if (refresh) {
        this.list = [];
        this.pageIndex = 1;
        this.hasMore = true;
      }
      if (!this.hasMore) return;

      this.loading = true;
      try {
        const res = await vk.callFunction({
          name: 'router',
          data: {
            action: 'customers/search', // 路由路径
            params: {
              keyword: this.keyword.trim(),
              pageIndex: this.pageIndex,
              pageSize: this.pageSize
            }
          }
        });
        // vk.callFunction 返回结构：{ code, data, msg }
        if (res.code === 0) {
          const { data, total } = res.data;
          this.list = [...this.list, ...data];
          this.hasMore = this.list.length < total;
          this.pageIndex++;
        } else {
          uni.showToast({ title: res.msg || '查询失败', icon: 'none' });
        }
      } catch (err) {
        uni.showToast({ title: '网络异常', icon: 'none' });
      } finally {
        this.loading = false;
      }
    },
    goDetail(id) {
      uni.navigateTo({
        url: `/pages/detail?id=${id}`
      });
    }
  }
};
</script>